INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2044, 'Les Liaisons dangereuses', 'Pierre-Ambroise-François Choderlos de Laclos', 'La marquise de Merteuil et le vicomte de Valmont, anciens amants, s''amusent à manipuler leur entourage. Valmont entreprend de séduire la vertueuse Madame de Tourvel, tandis que Merteuil se venge d''un ancien amant à travers la jeune Cécile. Un roman par lettres d''une noirceur et d''une intelligence redoutables.', 'livres/demo/9782070358410-generee.png', '9782070358410', 'Gallimard', 2008, 581, '18 cm', 'Poche', 4.80, 1, c.id_categorie, 'Folioplus classiques n° 5', 'Français', 'Première', 'Français' FROM categorie c WHERE c.slug = 'lycee';
