INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2102, 'L''Œil du loup', 'Daniel Pennac', 'Dans un zoo, un loup borgne tourne en rond dans son enclos et un garçon venu d''Afrique s''obstine à le regarder. Peu à peu, chacun raconte à l''autre son histoire à travers son œil : la traque dans le Grand Nord pour l''un, les déserts et les savanes pour l''autre. Un court roman sur l''amitié, l''exil et la nature blessée.', 'livres/demo/9782266294003-generee.png', '9782266294003', 'Pocket jeunesse', 2019, 104, '18 cm', 'Poche', 4.80, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'jeunesse';
