INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2103, 'Le Royaume de Kensuké', 'Michael Morpurgo', 'Michael part faire le tour du monde en voilier avec ses parents et leur chienne Stella. Une nuit de tempête, il passe par-dessus bord et échoue sur une île qu''il croit déserte. Quelqu''un pourtant lui laisse de l''eau et du poisson : Kensuké, un vieux Japonais qui vit là depuis la guerre. Une histoire de survie et de transmission.', 'livres/demo/9782070649716-generee.png', '9782070649716', 'Gallimard jeunesse', 2012, 149, '20 cm', 'Broché', 13.90, 1, c.id_categorie, 'Bibliothèque Gallimard jeunesse', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'jeunesse';
