INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2104, 'Fantastique Maître Renard', 'Roald Dahl', 'Trois fermiers aussi méchants que bêtes ont juré la perte de Maître Renard, qui vient chaque nuit chaparder poules et canards. Ils creusent, tirent, assiègent le terrier, mais le renard a plus d''un tour dans son sac pour nourrir sa famille et tous les animaux affamés du voisinage. Un petit roman malicieux à lire dès sept ans.', 'livres/demo/9782075097109-generee.png', '9782075097109', 'Gallimard jeunesse', 2018, 118, '19 cm', 'Poche', 8.90, 1, c.id_categorie, 'Folio cadet', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'jeunesse';
