INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2105, 'Persepolis', 'Marjane Satrapi', 'Marjane Satrapi raconte son enfance à Téhéran pendant la révolution islamique, puis la guerre contre l''Irak, son exil adolescent en Autriche et son retour au pays. En noir et blanc, avec humour et une grande franchise, elle montre comment l''histoire d''un pays bouleverse la vie d''une famille. Un récit autobiographique devenu incontournable.', 'livres/demo/9782844149596-generee.png', '9782844149596', 'L''Association', 2024, 356, '25 cm', 'Cartonné', 39.00, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'bandes-dessinees';
