INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2106, 'Le Chat du rabbin - Tome 1 : La Bar-Mitsva', 'Joann Sfar', 'Dans l''Alger des années 1930, le chat d''un rabbin dévore le perroquet de la maison et se met soudain à parler. Il veut faire sa bar-mitsva, discute théologie avec son maître et ne cache rien de son amour pour la belle Zlabya. Une bande dessinée drôle et tendre sur la foi, le doute et le vivre-ensemble.', 'livres/demo/9782205066456-generee.png', '9782205066456', 'Dargaud', 2010, 48, '30 cm', 'Cartonné', 11.95, 1, c.id_categorie, 'Le chat du rabbin n° 1', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'bandes-dessinees';
