INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2107, 'Les Vieux Fourneaux - Tome 1 : Ceux qui restent', 'Wilfrid Lupano, Paul Cauuet', 'Pierrot, Mimile et Antoine, trois amis d''enfance septuagénaires, se retrouvent à l''enterrement de la femme d''Antoine. Une vieille lettre révèle à ce dernier un secret qui le jette sur les routes de Toscane, ses amis à ses trousses. Une comédie pleine de mauvaise foi, d''anarchisme joyeux et de tendresse entre générations.', 'livres/demo/9782505073024-generee.png', '9782505073024', 'Dargaud', 2018, 56, '30cm', 'Cartonné', 13.00, 1, c.id_categorie, 'Les vieux fourneaux n° 1', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'bandes-dessinees';
