INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2108, 'Culottées - Tome 1', 'Pénélope Bagieu', 'Quinze portraits de femmes qui ont choisi de vivre comme elles l''entendaient : une impératrice, une gardienne de phare, une rappeuse afghane, une inventrice de la nage synchronisée… Pénélope Bagieu raconte en quelques planches colorées des destins souvent méconnus, avec beaucoup d''humour et d''admiration.', 'livres/demo/9782075211956-generee.png', '9782075211956', 'Gallimard bande dessinée', 2024, 140, '20 cm', 'Cartonné', 12.00, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'bandes-dessinees';
