INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2109, 'Maus', 'Art Spiegelman', 'Art Spiegelman interroge son père Vladek, survivant d''Auschwitz, et met en images son témoignage : les Juifs y sont des souris, les nazis des chats. Entre la Pologne des années 1940 et le New York des années 1970, l''album montre aussi la relation difficile entre un fils et son père. Une œuvre majeure sur la mémoire de la Shoah.', 'livres/demo/9782081494817-generee.png', '9782081494817', 'Flammarion', 2019, 135, '25 cm', 'Cartonné', 30.00, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'bandes-dessinees';
