INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2110, 'V pour Vendetta', 'Alan Moore, David Lloyd', 'Dans une Angleterre devenue dictature après une guerre nucléaire, un justicier masqué qui se fait appeler V fait sauter des bâtiments officiels et défie le pouvoir. Il recueille Evey, une jeune femme qu''il va pousser à se libérer de la peur. Un récit sombre et politique sur la liberté et la manipulation des foules.', 'livres/demo/9791026827474-generee.png', '9791026827474', 'Urban Comics', 2023, 343, '22 cm', 'Broché', 9.90, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'comics';
