INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2111, 'Batman : Année un', 'Frank Miller, David Mazzucchelli', 'Bruce Wayne revient à Gotham après des années d''entraînement et cherche comment mener sa guerre contre le crime. Au même moment, le lieutenant James Gordon arrive dans une police gangrenée par la corruption. Leurs deux trajectoires se croisent dans ce récit des débuts du Chevalier noir, sobre et réaliste.', 'livres/demo/9791026817284-generee.png', '9791026817284', 'Urban Comics', 2020, 104, '29 cm', 'Broché', 15.00, 1, c.id_categorie, 'Collection DC black label', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'comics';
