INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2112, 'Saga - Tome 1', 'Brian K. Vaughan, Fiona Staples', 'Alana et Marko appartiennent à deux peuples en guerre depuis toujours. Ils sont tombés amoureux et viennent d''avoir une fille, ce qui fait d''eux des fugitifs traqués par les deux camps. Un space opera inventif et souvent cru, raconté par leur enfant, qui parle surtout de famille et de survie.', 'livres/demo/9791026820291-generee.png', '9791026820291', 'Urban Comics', 2025, 311, '32 cm', 'Broché', 15.95, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'comics';
