INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2113, 'Death Note - Tome 1', 'Tsugumi Ōba, Takeshi Obata', 'Light Yagami, lycéen brillant, ramasse un cahier tombé du ciel : quiconque y voit son nom écrit meurt. Il décide de débarrasser le monde des criminels, jusqu''à ce qu''un détective excentrique, L, se lance à sa poursuite. Un duel intellectuel haletant entre deux génies, et une réflexion sur la justice.', 'livres/demo/9782505000327.jpg', '9782505000327', 'Kana', 2007, 184, '18 cm', 'Broché', 5.95, 1, c.id_categorie, 'Dark Kana', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'mangas';
