INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2114, 'L''Attaque des Titans - Tome 1', 'Hajime Isayama', 'L''humanité survit derrière d''immenses murailles qui la protègent de Titans géants dévorant les humains. Le jour où l''un d''eux brise le mur, le jeune Eren voit sa ville envahie et sa mère disparaître. Il s''engage alors dans l''armée pour reconquérir le monde extérieur. Le début d''une saga sombre et spectaculaire.', 'livres/demo/9782811611699.jpg', '9782811611699', 'Pika', 2013, 192, '18 cm', 'Broché', 6.95, 1, c.id_categorie, 'Seinen', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'mangas';
