INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2115, 'Naruto - Tome 1', 'Masashi Kishimoto', 'Naruto Uzumaki, apprenti ninja turbulent et rejeté par son village, rêve de devenir Hokage, le plus puissant de tous. Il ignore encore pourquoi les adultes se méfient de lui. Avec Sasuke et Sakura, il commence ses premières missions sous la direction du mystérieux Kakashi. Un classique du manga d''aventure.', 'livres/demo/9782871294146.jpg', '9782871294146', 'Kana', 2002, 187, '18 cm', 'Broché', 5.25, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'mangas';
