INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2117, 'Frieren - Tome 1', 'Kanehito Yamada, Tsukasa Abe', 'Après avoir vaincu le roi des démons, l''elfe magicienne Frieren voit ses compagnons humains vieillir puis disparaître, alors que pour elle dix ans ne sont rien. Elle repart sur les routes pour comprendre ce qu''elle a vécu avec eux. Une fantasy mélancolique et douce sur le temps qui passe et les liens.', 'livres/demo/9791032710838.jpg', '9791032710838', 'Ki-oon', 2022, 114, '18 cm', 'Broché', 7.90, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'mangas';
