INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2118, 'Le Gruffalo', 'Julia Donaldson, Axel Scheffler', 'Une petite souris se promène dans les bois et croise un renard, un hibou puis un serpent qui rêvent de la croquer. Pour leur échapper, elle invente un monstre terrible, le Gruffalo, qui serait son ami. Mais que faire quand le Gruffalo existe vraiment ? Un album rimé, drôle et parfait à lire à voix haute.', 'livres/demo/9782075210065-generee.png', '9782075210065', 'Gallimard jeunesse', 2024, 37, '28 cm', 'Cartonné', 14.90, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'albums';
