INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2119, 'Petit-Bleu et Petit-Jaune', 'Leo Lionni', 'Petit-Bleu et Petit-Jaune sont les meilleurs amis du monde. Un jour, ils se serrent si fort qu''ils deviennent tout verts, et leurs parents ne les reconnaissent plus. Avec de simples taches de couleur, Leo Lionni raconte l''amitié, la différence et le mélange. Un album fondateur pour les tout-petits.', 'livres/demo/9782211310635-generee.png', '9782211310635', 'L''École des loisirs', 2020, 41, '21 cm', 'Cartonné', 10.50, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'albums';
