INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2120, 'Les Trois Brigands', 'Tomi Ungerer', 'Trois brigands vêtus de grands manteaux noirs terrorisent la campagne avec leur tromblon, leur soufflet à poivre et leur hache rouge. Une nuit, ils arrêtent une diligence où ne voyage qu''une petite orpheline, Tiffany, qui leur demande ce qu''ils font de tout leur or. Un album à la fois effrayant et réconfortant.', 'livres/demo/9782211232579.jpg', '9782211232579', 'l''École des loisirs', 2017, 38, '17 cm', 'Poche', 6.50, 1, c.id_categorie, 'Petite bibliothèque de l''École des loisirs', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'albums';
