INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2121, 'Loulou', 'Grégoire Solotareff', 'Tom, un jeune lapin, rencontre Loulou, un jeune loup qui n''a jamais appris à chasser. Ils deviennent inséparables et jouent même à se faire peur, jusqu''au jour où le jeu va trop loin. Un album aux couleurs franches qui parle de l''amitié entre deux êtres que tout devait opposer.', 'livres/demo/9782211335232-generee.png', '9782211335232', 'L''École des loisirs', 2024, 41, '32 cm', 'Cartonné', 19.90, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'albums';
