INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2122, 'Nos étoiles contraires', 'John Green', 'Hazel, seize ans, vit avec un cancer qui l''oblige à traîner partout une bouteille d''oxygène. Au groupe de soutien qu''elle fréquente à contrecœur, elle rencontre Augustus, drôle, insolent et en rémission. Ensemble, ils partent à Amsterdam rencontrer l''auteur de son roman préféré. Une histoire d''amour lucide et pleine d''humour.', 'livres/demo/9782266283304.jpg', '9782266283304', 'Pocket jeunesse', 2017, 372, '18 cm', 'Poche', 7.40, 1, c.id_categorie, 'Pocket jeunesse n° J3113', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'ados';
