INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2123, 'Divergente - Tome 1', 'Veronica Roth', 'Dans un Chicago futuriste, la société est divisée en cinq factions selon les qualités de chacun. À seize ans, Tris doit choisir la sienne pour la vie, mais le test révèle qu''elle est divergente, un statut dangereux qu''elle doit cacher. Elle quitte sa famille pour la faction des Audacieux, la plus brutale.', 'livres/demo/9782092552988.jpg', '9782092552988', 'Nathan', 2014, 445, '23 cm', 'Broché', 16.90, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'ados';
