INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2124, 'L''Élégance du hérisson', 'Muriel Barbery', 'Renée, concierge d''un immeuble bourgeois parisien, cache sous des airs bougons une immense culture. Paloma, douze ans, fille surdouée d''une famille du quatrième, a décidé d''en finir le jour de ses treize ans. L''arrivée d''un nouveau voisin japonais va rapprocher ces deux solitudes. Un roman drôle et sensible.', 'livres/demo/9782070391653.jpg', '9782070391653', 'Gallimard', 2009, 413, '18 cm', 'Poche', 7.60, 1, c.id_categorie, 'Collection Folio n° 4939', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'roman';
