INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2125, 'Veiller sur elle', 'Jean-Baptiste Andrea', 'Dans l''Italie du début du XXe siècle, Mimo, apprenti sculpteur de petite taille, rencontre Viola Orsini, fille d''une puissante famille aristocratique. Entre eux naît un lien indéfectible, traversé par les guerres, le fascisme et les interdits sociaux. Une grande fresque romanesque, récompensée par le prix Goncourt 2023.', 'livres/demo/9782378803759-generee.png', '9782378803759', 'L''Iconoclaste', 2023, 580, '20 cm', 'Broché', 21.50, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'roman';
