INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2126, 'Les Choses humaines', 'Karine Tuil', 'Les Farel forment un couple de pouvoir : lui est un journaliste politique célèbre, elle une essayiste reconnue, leur fils étudie aux États-Unis. Une accusation de viol portée contre ce fils fait voler en éclats cette réussite. Le roman suit l''enquête puis le procès, et interroge la notion de consentement.', 'livres/demo/9782072921117.jpg', '9782072921117', 'Gallimard', 2021, 341, '18 cm', 'Poche', 8.10, 1, c.id_categorie, 'Collection Folio n° 6887', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'roman';
