INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2127, 'La Horde du Contrevent', 'Alain Damasio', 'Sur une terre balayée par des vents incessants, une horde de vingt-trois personnes remonte à pied vers l''Extrême-Amont, là où le vent est censé naître. Chacun a son rôle et sa voix, et le roman alterne leurs points de vue, typographie à l''appui. Une épopée exigeante et éblouissante de la science-fiction française.', 'livres/demo/9782072822049.jpg', '9782072822049', 'Gallimard', 2018, 700, '18 cm', 'Poche', 12.00, 1, c.id_categorie, 'Folio', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'science-fiction';
