INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2128, 'Fondation', 'Isaac Asimov', 'Le mathématicien Hari Seldon a calculé que l''Empire galactique allait s''effondrer et plonger l''humanité dans trente mille ans de barbarie. Pour réduire cette période à mille ans, il crée la Fondation, chargée de préserver le savoir. Une suite de récits sur la politique, la science et la manipulation de l''histoire.', 'livres/demo/9782070360536.jpg', '9782070360536', 'Gallimard', 2009, 402, '18 cm', 'Poche', 5.50, 1, c.id_categorie, 'Le cycle de Fondation n° 1', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'science-fiction';
