INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2129, 'Fahrenheit 451', 'Ray Bradbury', 'Montag est pompier, mais dans son monde les pompiers ne combattent pas le feu : ils brûlent les livres, interdits parce qu''ils rendraient malheureux. Une rencontre avec une jeune voisine curieuse le pousse à garder un livre au lieu de le détruire. Un classique de l''anticipation sur la censure et le conformisme.', 'livres/demo/9782072892950.jpg', '9782072892950', 'Gallimard', 2020, 236, '18 cm', 'Poche', 6.30, 1, c.id_categorie, 'Folio', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'science-fiction';
