INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2130, 'Le Nom du vent', 'Patrick Rothfuss', 'Kvothe, devenu aubergiste sous un faux nom, accepte de raconter sa vraie vie à un chroniqueur : son enfance dans une troupe de comédiens, le massacre de sa famille, ses années de misère puis son entrée à l''Université pour apprendre la magie. Une fantasy ample et musicale, portée par un narrateur fascinant.', 'livres/demo/9782352949152-generee.png', '9782352949152', 'Bragelonne', 2015, 781, '24 cm', 'Broché', 40.00, 1, c.id_categorie, 'Chronique du tueur de roi n° 1re journée', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'science-fiction';
