INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2131, 'Le Silence des agneaux', 'Thomas Harris', 'Clarice Starling, jeune stagiaire du FBI, est chargée d''interroger le docteur Hannibal Lecter, psychiatre brillant et cannibale enfermé dans une cellule de haute sécurité. Elle espère qu''il l''aidera à identifier un tueur en série qui sévit en ce moment. S''engage entre eux un jeu psychologique glaçant.', 'livres/demo/9782266120159.jpg', '9782266120159', 'Pocket', 2002, 377, '18 cm', 'Poche', 8.40, 1, c.id_categorie, 'Pocket n° 11542', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'policier-thriller';
