INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2132, 'Glacé', 'Bernard Minier', 'Dans une vallée des Pyrénées, des ouvriers découvrent le cadavre décapité d''un cheval suspendu au-dessus d''une centrale. Le commandant Servaz enquête et remonte jusqu''à un institut psychiatrique voisin où est enfermé un tueur en série redoutable. Un premier thriller très sombre dans un décor de neige.', 'livres/demo/9782266269193-generee.png', '9782266269193', 'Pocket', 2016, 729, '18 cm', 'Poche', 9.00, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'policier-thriller';
