INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2133, 'Ils étaient dix', 'Agatha Christie', 'Dix personnes qui ne se connaissent pas sont invitées sur une île isolée par un hôte qui ne se montre jamais. Le premier soir, une voix les accuse chacune d''un crime resté impuni. Puis, un à un, les invités meurent selon les couplets d''une comptine. Le roman le plus célèbre d''Agatha Christie.', 'livres/demo/9782253241553-generee.png', '9782253241553', 'Le Livre de poche', 2021, 283, '18 cm', 'Poche', 6.90, 1, c.id_categorie, 'Le livre de poche n° 35807', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'policier-thriller';
