INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2134, 'Orgueil et préjugés', 'Jane Austen', 'Mrs Bennet n''a qu''une idée : marier ses cinq filles. Quand le riche Mr Bingley s''installe dans le voisinage avec son ami Mr Darcy, Elizabeth, la deuxième, juge ce dernier hautain et insupportable. Mais les premières impressions sont parfois trompeuses. Une comédie de mœurs vive, ironique et toujours moderne.', 'livres/demo/9791041427925-generee.png', '9791041427925', 'Points', 2026, 470, '19 cm', 'Broché', 10.20, 1, c.id_categorie, 'Classiques', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'romance';
