INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2135, 'Un jour', 'David Nicholls', 'Le 15 juillet 1988, Emma et Dexter passent ensemble la nuit qui suit la remise de leurs diplômes. Le roman les retrouve ensuite le même jour chaque année pendant vingt ans : amitié, malentendus, réussites, échecs et occasions manquées. Une histoire d''amour drôle et douce-amère sur le temps qui passe.', 'livres/demo/9782266224161-generee.png', '9782266224161', 'Pocket', 2020, 665, '18 cm', 'Poche', 9.50, 1, c.id_categorie, 'Pocket n° 15015', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'romance';
