INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2136, 'Alcools', 'Guillaume Apollinaire', 'Publié en 1913, ce recueil rassemble quinze ans de poèmes, de « Zone » au « Pont Mirabeau » en passant par « La Chanson du mal-aimé ». Apollinaire y supprime la ponctuation et mêle tradition lyrique, mythes, souvenirs amoureux et modernité urbaine. Une porte d''entrée idéale vers la poésie du XXe siècle.', 'livres/demo/9782070300075.jpg', '9782070300075', 'Gallimard', 1994, 190, '18 cm', 'Poche', 8.40, 1, c.id_categorie, 'Poésie n° 10', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'poesie-theatre';
