INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2137, 'Paroles', 'Jacques Prévert', 'Des poèmes devenus familiers, comme « Barbara », « Le Cancre » ou « Déjeuner du matin », écrits dans une langue simple, joueuse et tendre. Prévert y célèbre l''amour, l''enfance et la liberté, et se moque de la guerre, de l''Église et des puissants. Le recueil de poésie le plus lu en France.', 'livres/demo/9782070793969-generee.png', '9782070793969', 'Gallimard', 2016, 253, '18 cm', 'Poche', 9.70, 1, c.id_categorie, 'Collection Folio', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'poesie-theatre';
