INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2138, 'En attendant Godot', 'Samuel Beckett', 'Au bord d''une route, près d''un arbre, Vladimir et Estragon attendent un certain Godot qui ne vient jamais. Pour passer le temps, ils parlent, se disputent, mangent des carottes et croisent un maître et son esclave. Une pièce à la fois comique et vertigineuse, qui a renouvelé le théâtre du XXe siècle.', 'livres/demo/9782707301482-generee.png', '9782707301482', 'Les Éditions de Minuit', 2009, 124, '18 cm', 'Poche', 8.40, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'poesie-theatre';
