INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2139, 'Huis clos', 'Jean-Paul Sartre', 'Trois morts, Garcin, Inès et Estelle, sont enfermés ensemble dans un salon Second Empire sans fenêtre ni miroir. Ils s''attendaient à des flammes et à des bourreaux, mais l''enfer prend une autre forme. Une courte pièce en un acte qui se termine par une réplique devenue célèbre : « L''enfer, c''est les autres ».', 'livres/demo/9782070368075.jpg', '9782070368075', 'Gallimard', 1994, 247, '18 cm', 'Poche', 8.40, 1, c.id_categorie, 'Folio n° 807', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'poesie-theatre';
