INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2140, 'Le Comte de Monte-Cristo - Tome 1', 'Alexandre Dumas', 'Le jeune marin Edmond Dantès est arrêté le jour de ses fiançailles, victime d''une dénonciation calomnieuse, et jeté au château d''If. Après quatorze ans de captivité, il s''évade, devient immensément riche grâce au trésor de son compagnon de cellule, et revient sous un nouveau nom pour se venger.', 'livres/demo/9782073131317-generee.png', '9782073131317', 'Gallimard', 2026, 857, '18 cm', 'Poche', 9.50, 1, c.id_categorie, 'Folio n° 3142', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'classiques';
