INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2141, 'Germinal', 'Émile Zola', 'Étienne Lantier, ouvrier sans travail, se fait embaucher dans une mine du Nord. Il découvre la misère des familles de mineurs, la dureté des conditions de travail et la colère qui monte. Quand la compagnie baisse les salaires, il pousse à la grève. Un grand roman social, puissant et toujours actuel.', 'livres/demo/9782070411429.jpg', '9782070411429', 'Gallimard', 1999, 638, '18 cm', 'Poche', 8.40, 1, c.id_categorie, 'Collection Folio', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'classiques';
