INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2142, 'Le Rouge et le Noir', 'Stendhal', 'Julien Sorel, fils de charpentier ambitieux et admirateur de Napoléon, devient précepteur chez le maire de Verrières, puis séminariste, puis secrétaire d''un marquis parisien. Entre calcul et passion, il tente de s''élever dans une société de la Restauration qui méprise les pauvres. Un roman d''apprentissage et de révolte.', 'livres/demo/9782072908941-generee.png', '9782072908941', 'Gallimard', 2020, 864, '18 cm', 'Poche', 4.00, 1, c.id_categorie, 'Folio', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'classiques';
