INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2143, 'Bel-Ami', 'Guy de Maupassant', 'Georges Duroy, ancien sous-officier sans le sou, croise un camarade qui le fait entrer dans un journal parisien. Séduisant et sans scrupule, il comprend vite que les femmes peuvent lui ouvrir les portes de la réussite. Maupassant dresse le portrait d''un arriviste et d''une presse liée à l''argent et à la politique.', 'livres/demo/9782072885068-generee.png', '9782072885068', 'Gallimard', 2020, 415, '18 cm', 'Poche', 4.50, 1, c.id_categorie, 'Folio+ lycée n° 13', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'classiques';
