INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2144, 'Sorcières', 'Mona Chollet', 'Partant des chasses aux sorcières de la Renaissance, Mona Chollet montre comment certaines figures de femmes continuent d''inquiéter : celles qui vivent seules, celles qui ne veulent pas d''enfants, celles qui vieillissent sans s''en cacher. Un essai documenté et accessible, devenu un succès de librairie.', 'livres/demo/9782355221224.jpg', '9782355221224', 'Zones', 2018, 231, '21 cm', 'Broché', 18.00, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'essai';
