INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2149, 'Si c''est un homme', 'Primo Levi', 'Arrêté en 1943 comme résistant, puis déporté à Auschwitz parce que juif, le chimiste italien Primo Levi raconte sa survie dans le camp. Il décrit avec précision et sans haine la faim, le froid, le travail et la déshumanisation organisée. Un témoignage essentiel sur la Shoah, d''une grande force morale.', 'livres/demo/9782266351416-generee.png', '9782266351416', 'Pocket', 2025, 277, '18 cm', 'Poche', 6.95, 1, c.id_categorie, 'Une oeuvre, une voix', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'histoire';
