INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2151, 'Van Gogh', 'Ingo F. Walther', 'Une monographie richement illustrée qui retrace la courte carrière de Vincent van Gogh, des sombres paysans du Brabant aux toiles éclatantes d''Arles et d''Auvers. Le texte suit l''évolution de sa peinture, ses influences et ses lettres à son frère Théo. Une introduction claire et accessible à son œuvre.', 'livres/demo/9783836541213-generee.png', '9783836541213', 'Taschen', 2012, 740, '28 cm', 'Broché', 29.90, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'arts-photographie';
