INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2154, 'Dans les forêts de Sibérie', 'Sylvain Tesson', 'Sylvain Tesson a passé six mois seul dans une cabane au bord du lac Baïkal, à plusieurs jours de marche du premier village. Il tient le journal de ces jours de froid, de lecture, de pêche et de vodka, face à la forêt et à la glace. Un récit sur la solitude, la lenteur et le plaisir de vivre simplement.', 'livres/demo/9782072821974-generee.png', '9782072821974', 'Gallimard', 2018, 289, '18 cm', 'Poche', 8.60, 1, c.id_categorie, 'Collection Folio', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'voyages';
