INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2155, 'Into the wild', 'Jon Krakauer', 'En 1992, le corps de Chris McCandless, vingt-quatre ans, est retrouvé dans un bus abandonné en Alaska. Brillant diplômé, il avait donné ses économies, coupé les ponts avec sa famille et pris la route sous un autre nom. Le journaliste Jon Krakauer reconstitue son parcours et tente de comprendre son choix.', 'livres/demo/9782264079534-generee.png', '9782264079534', '10-18', 2021, 306, '18 cm', 'Poche', 8.50, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'voyages';
