INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2160, 'Freakonomics', 'Steven D. Levitt, Stephen J. Dubner', 'Pourquoi les dealers vivent-ils souvent chez leur mère ? Les agents immobiliers vendent-ils leur propre maison au même prix que celle de leurs clients ? Un économiste et un journaliste utilisent les outils de l''économie pour répondre à des questions inattendues. Un livre ludique sur les incitations et les statistiques.', 'livres/demo/9782070341795.jpg', '9782070341795', 'Gallimard', 2007, NULL, '18 cm', 'Poche', 6.60, 1, c.id_categorie, 'Folio n° 132', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'economie-entreprise';
