INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2165, 'L''Erreur de Descartes', 'Antonio R. Damasio', 'Le neurologue Antonio Damasio montre, à partir de patients atteints de lésions cérébrales, que la raison ne fonctionne pas sans les émotions. Ceux qui ne ressentent plus rien prennent des décisions désastreuses. Un essai marquant sur le cerveau, le corps et la manière dont nous faisons nos choix.', 'livres/demo/9782738124579-generee.png', '9782738124579', 'Odile Jacob', 2010, 396, '18 cm', 'Poche', 10.50, 1, c.id_categorie, 'Odile Jacob poches', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'sante';
