INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2181, 'One Punch Man - Tome 1', 'ONE, Yusuke Murata', 'Saitama est devenu si fort qu''il terrasse n''importe quel monstre d''un seul coup de poing. Résultat : il s''ennuie terriblement et cherche un adversaire digne de lui. Une parodie de manga de super-héros, aux combats spectaculaires et au héros chauve et blasé, qui joue avec tous les clichés du genre.', 'livres/demo/9791042020613-generee.png', '9791042020613', 'Kurokawa', 2025, 189, '18 cm', 'Broché', 7.30, 1, c.id_categorie, 'Collection dirigée par Grégoire Hellot', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'mangas';
