INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2182, 'Ma vie avec Mozart', 'Éric-Emmanuel Schmitt', 'Adolescent, Éric-Emmanuel Schmitt traversait une période sombre lorsqu''il a entendu un air de Mozart qui l''a réconcilié avec la vie. Depuis, il écrit au compositeur des lettres où il évoque ses doutes, ses joies et ses découvertes. Un livre intime sur le pouvoir consolant de la musique.', 'livres/demo/9782226168207.jpg', '9782226168207', 'Albin Michel', 2005, 159, '20 cm', 'Broché', 22.90, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'musique';
