INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2183, 'Voir le voir', 'John Berger', 'À partir d''une célèbre série télévisée des années 1970, John Berger montre que notre manière de regarder les images est façonnée par l''histoire, l''argent et les rapports entre hommes et femmes. Peinture à l''huile, nus, publicité : il apprend à regarder autrement. Un petit livre devenu un classique.', 'livres/demo/9782917855508-generee.png', '9782917855508', 'Éditions B42', 2014, 166, '20 cm', 'Broché', 22.00, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'arts-photographie';
