INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2184, 'Pourquoi nous dormons', 'Matthew Walker', 'Le neuroscientifique Matthew Walker explique à quoi sert le sommeil et ce qui se passe quand on en manque : mémoire, créativité, immunité, poids, humeur et risques de maladies. Il démonte des idées reçues et donne des conseils pour mieux dormir. Un livre de vulgarisation qui fait prendre le sommeil au sérieux.', 'livres/demo/9782266287234-generee.png', '9782266287234', 'Pocket', 2019, 546, '18 cm', 'Poche', 8.30, 1, c.id_categorie, 'Pocket', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'sante';
