INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2185, 'Les Décisions absurdes', 'Christian Morel', 'Pourquoi des équipes compétentes prennent-elles parfois des décisions radicalement contraires à leur but ? Le sociologue Christian Morel analyse des cas réels, de l''aviation à l''industrie, et montre le rôle des erreurs de raisonnement, de la communication et de l''organisation. Un essai éclairant sur le fonctionnement des groupes.', 'livres/demo/9782070315420.jpg', '9782070315420', 'Gallimard', 2004, 379, '18 cm', 'Poche', 6.00, 1, c.id_categorie, 'Folio n° 445', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'economie-entreprise';
