INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2189, 'Ikigai', 'Héctor García, Francesc Miralles', 'Sur l''île d''Okinawa, au Japon, vivent un grand nombre de centenaires. Les auteurs sont allés à leur rencontre pour comprendre leur secret : avoir un ikigai, une raison d''être qui donne envie de se lever le matin. Alimentation, activité, liens sociaux : un petit livre qui invite à réfléchir à ce qui compte.', 'livres/demo/9782266286688.jpg', '9782266286688', 'Pocket', 2018, 189, '18 cm', 'Poche', 6.95, 1, c.id_categorie, 'Pocket', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'developpement-personnel';
