INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2190, 'L''Alchimiste', 'Paulo Coelho', 'Santiago, jeune berger andalou, fait plusieurs fois le même rêve : un trésor l''attend au pied des pyramides d''Égypte. Il vend son troupeau et traverse le détroit puis le désert, guidé par des signes et par la rencontre d''un alchimiste. Un conte philosophique simple sur l''écoute de soi et la poursuite de ses rêves.', 'livres/demo/9782290258064.jpg', '9782290258064', 'J''ai lu', 2021, 190, '18 cm', 'Poche', 7.10, 1, c.id_categorie, 'J''ai lu n° 4120', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'roman';
