INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2191, 'Le Parfum', 'Patrick Süskind', 'Dans la France du XVIIIe siècle naît Jean-Baptiste Grenouille, un enfant sans aucune odeur mais doté d''un odorat prodigieux. Devenu apprenti parfumeur, il n''a qu''une obsession : capturer le parfum parfait, quitte à tuer pour l''obtenir. Un roman troublant, à la fois conte noir et histoire d''un monstre.', 'livres/demo/9782253123460-generee.png', '9782253123460', 'Librairie générale française', 2007, 279, '18 cm', 'Poche', 8.00, 1, c.id_categorie, 'Le livre de poche n° 30913', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'policier-thriller';
