INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2192, 'La Vie devant soi', 'Romain Gary (Émile Ajar)', 'Momo, petit garçon arabe, grandit à Belleville chez Madame Rosa, ancienne prostituée juive qui élève les enfants des « femmes qui se défendent ». Elle vieillit et sa santé décline, et Momo veille sur elle avec une tendresse farouche. Un roman bouleversant et drôle, prix Goncourt 1975 sous le pseudonyme d''Émile Ajar.', 'livres/demo/9782072915291-generee.png', '9782072915291', 'Gallimard', 2020, 273, '18 cm', 'Poche', 8.50, 1, c.id_categorie, 'Collection Folio', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'classiques';
