INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2193, 'L''Ami retrouvé', 'Fred Uhlman', 'Stuttgart, 1932. Hans, fils d''un médecin juif, se lie d''amitié avec Conrad, héritier d''une grande famille aristocratique. Leur complicité de lycéens est bientôt brisée par la montée du nazisme. Un court roman, très lu au collège, sur l''amitié, la trahison et l''aveuglement d''une époque.', 'livres/demo/9782070659852-generee.png', '9782070659852', 'Gallimard jeunesse', 2014, 119, '18 cm', 'Poche', 6.00, 1, c.id_categorie, 'Folio junior', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'classiques';
