INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2194, 'Sa Majesté des mouches', 'William Golding', 'Après un accident d''avion, des garçons britanniques se retrouvent seuls sur une île déserte. Ils tentent d''abord de s''organiser comme des adultes, avec des règles et un chef. Mais la peur et la violence prennent peu à peu le dessus. Une fable glaçante sur la part sauvage de l''être humain.', 'livres/demo/9782075120401-generee.png', '9782075120401', 'Gallimard jeunesse', 2020, 321, '18 cm', 'Poche', 8.50, 1, c.id_categorie, 'Folio junior', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'classiques';
