INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2195, 'Le Vieil Homme et la mer', 'Ernest Hemingway', 'Santiago, vieux pêcheur cubain, n''a rien pris depuis quatre-vingt-quatre jours. Il part seul en haute mer et ferre un espadon gigantesque qui l''entraîne pendant trois jours. Commence un combat épuisant entre l''homme et le poisson, puis contre les requins. Un court récit sur le courage et la dignité.', 'livres/demo/9782072762086-generee.png', '9782072762086', 'Gallimard', 2018, 135, '18 cm', 'Poche', 6.00, 1, c.id_categorie, 'Collection Folio n° 6487', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'classiques';
