INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2196, 'Le Liseur', 'Bernhard Schlink', 'À quinze ans, Michaël vit une liaison avec Hanna, une femme plus âgée à qui il fait la lecture. Elle disparaît du jour au lendemain. Des années plus tard, étudiant en droit, il la retrouve sur le banc des accusés d''un procès de gardiennes de camp nazi. Un roman sur la culpabilité et la mémoire allemande.', 'livres/demo/9782072961700-generee.png', '9782072961700', 'Gallimard', 2022, 463, '18 cm', 'Poche', 13.00, 1, c.id_categorie, 'Folio n° 236', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'roman';
