INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2197, 'Le Meilleur des mondes', 'Aldous Huxley', 'Dans un futur où les enfants sont fabriqués en laboratoire et conditionnés selon leur caste, tout le monde est heureux grâce aux loisirs et à une drogue, le soma. Bernard Marx, qui ne se sent pas à sa place, ramène d''une réserve un « Sauvage » élevé hors du système. Une dystopie classique sur le bonheur imposé.', 'livres/demo/9782266346849-generee.png', '9782266346849', 'Pocket', 2024, 349, '18 cm', 'Poche', 9.00, 1, c.id_categorie, NULL, 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'science-fiction';
