INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2198, 'Chroniques martiennes', 'Ray Bradbury', 'De 1999 à 2026, les Terriens envoient expédition après expédition sur Mars, puis s''y installent, alors que les Martiens disparaissent. À travers une suite de récits poétiques et souvent cruels, Ray Bradbury raconte la colonisation d''une planète et les travers de l''humanité qui l''accompagnent.', 'livres/demo/9782070417742-generee.png', '9782070417742', 'Gallimard', 2001, 318, '18 cm', 'Poche', 8.40, 1, c.id_categorie, 'Folio n° 45', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'science-fiction';
