INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2199, 'Tintin au Tibet', 'Hergé', 'En vacances dans les Alpes, Tintin apprend que l''avion de son ami Tchang s''est écrasé dans l''Himalaya. Persuadé que Tchang a survécu, il part à sa recherche avec Milou et le capitaine Haddock, malgré la neige, le froid et la rumeur d''un mystérieux yéti. L''album le plus personnel d''Hergé, sur l''amitié et la fidélité.', 'livres/demo/9782203007642-generee.png', '9782203007642', 'Casterman', 2007, 62, '23 cm', 'Cartonné', 5.95, 1, c.id_categorie, 'Les aventures de Tintin n° 20', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'bandes-dessinees';
