INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2200, 'Le Monde de Sophie', 'Jostein Gaarder', 'Sophie, quatorze ans, trouve dans sa boîte aux lettres deux questions : « Qui es-tu ? » et « D''où vient le monde ? ». Un mystérieux professeur lui envoie ensuite un cours de philosophie, des présocratiques à Sartre. Un roman qui raconte l''histoire de la pensée occidentale comme une enquête.', 'livres/demo/9782757883334-generee.png', '9782757883334', 'Points', 2020, 623, '18 cm', 'Poche', 10.00, 1, c.id_categorie, 'Points n° P1000', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'essai';
