INSERT IGNORE INTO livre (id_livre, titre, auteur, description, couverture, isbn, editeur, annee_parution, nb_pages, dimensions, reliure, prix, is_valide, id_categorie, collection, langue, niveau_scolaire, matiere) SELECT 2201, 'Les Années', 'Annie Ernaux', 'À partir de photos et de souvenirs, Annie Ernaux raconte sa vie et, en même temps, celle de toute une génération, de l''après-guerre jusqu''aux années 2000. Elle écrit à la troisième personne, avec le « on » et le « nous », pour saisir ce qui a changé dans la société, les objets, les mots et les façons de vivre.', 'livres/demo/9782070402472.jpg', '9782070402472', 'Gallimard', 2009, 253, '18 cm', 'Poche', 6.60, 1, c.id_categorie, 'Collection Folio n° 5000', 'Français', NULL, NULL FROM categorie c WHERE c.slug = 'roman';
