INSERT IGNORE INTO fiche_auteur (id_user, nom_plume, slug, biographie, lien_site) SELECT id, 'Élise Marchand', 'elise-marchand', 'Lyonnaise d''adoption, Élise Marchand a longtemps travaillé dans une librairie de la Croix-Rousse avant de se consacrer à l''écriture. Elle aime les intrigues qui prennent le temps d''installer un quartier, ses commerces et ses habitants. Son premier polar, Les Ombres de la Croix-Rousse, met en scène la commandante Salomé Ferrand au milieu des traboules et des bouquinistes.', NULL FROM `user` WHERE id = 1001 AND role = 'auteur';
INSERT INTO fiche_auteur_ouvrage (id_user, titre, editeur, annee, ordre) SELECT 1001, 'Les Ombres de la Croix-Rousse', 'Autoédition', 2026, 0 FROM DUAL WHERE EXISTS (SELECT 1 FROM fiche_auteur WHERE id_user = 1001) AND NOT EXISTS (SELECT 1 FROM fiche_auteur_ouvrage WHERE id_user = 1001 AND titre = 'Les Ombres de la Croix-Rousse');
INSERT IGNORE INTO fiche_auteur (id_user, nom_plume, slug, biographie, lien_site) SELECT id, 'Bastien Lemoine', 'bastien-lemoine', 'Illustrateur installé à Villeurbanne, Bastien Lemoine dessine depuis l''enfance des animaux qui parlent et des machines impossibles. Il a créé la série Pixel et Moustache pour les lecteurs de 6 à 10 ans : des histoires courtes, beaucoup d''humour et des planches pleines de détails à découvrir à chaque relecture.', NULL FROM `user` WHERE id = 1002 AND role = 'auteur';
INSERT INTO fiche_auteur_ouvrage (id_user, titre, editeur, annee, ordre) SELECT 1002, 'Pixel et Moustache - Tome 1 : Le chat qui voulait voler', 'Autoédition', 2025, 0 FROM DUAL WHERE EXISTS (SELECT 1 FROM fiche_auteur WHERE id_user = 1002) AND NOT EXISTS (SELECT 1 FROM fiche_auteur_ouvrage WHERE id_user = 1002 AND titre = 'Pixel et Moustache - Tome 1 : Le chat qui voulait voler');
INSERT INTO fiche_auteur_ouvrage (id_user, titre, editeur, annee, ordre) SELECT 1002, 'Pixel et Moustache - Tome 2 : Panique au musée', 'Autoédition', 2026, 1 FROM DUAL WHERE EXISTS (SELECT 1 FROM fiche_auteur WHERE id_user = 1002) AND NOT EXISTS (SELECT 1 FROM fiche_auteur_ouvrage WHERE id_user = 1002 AND titre = 'Pixel et Moustache - Tome 2 : Panique au musée');
INSERT IGNORE INTO fiche_auteur (id_user, nom_plume, slug, biographie, lien_site) SELECT id, 'Margot Delaunay', 'margot-delaunay', 'Ancienne professeure de sciences de la vie à Brest, Margot Delaunay écrit des romans d''aventure pour les adolescents, toujours tournés vers la mer et la protection du littoral. Elle anime régulièrement des ateliers d''écriture dans les collèges du Finistère.', NULL FROM `user` WHERE id = 1121 AND role = 'auteur';
INSERT INTO fiche_auteur_ouvrage (id_user, titre, editeur, annee, ordre) SELECT 1121, 'L''Été des grandes marées', 'Éditions du Ponant', 2023, 0 FROM DUAL WHERE EXISTS (SELECT 1 FROM fiche_auteur WHERE id_user = 1121) AND NOT EXISTS (SELECT 1 FROM fiche_auteur_ouvrage WHERE id_user = 1121 AND titre = 'L''Été des grandes marées');
INSERT INTO fiche_auteur_ouvrage (id_user, titre, editeur, annee, ordre) SELECT 1121, 'Les Gardiens de la laisse de mer', 'Éditions du Ponant', 2025, 1 FROM DUAL WHERE EXISTS (SELECT 1 FROM fiche_auteur WHERE id_user = 1121) AND NOT EXISTS (SELECT 1 FROM fiche_auteur_ouvrage WHERE id_user = 1121 AND titre = 'Les Gardiens de la laisse de mer');
INSERT IGNORE INTO fiche_auteur (id_user, nom_plume, slug, biographie, lien_site) SELECT id, 'Samir Kaci', 'samir-kaci', 'Samir Kaci a grandi à Vaulx-en-Velin et travaille comme éducateur sportif. Il écrit des nouvelles courtes et rythmées sur la vie de quartier, le football amateur et l''amitié. Son recueil Coup franc a été lu dans plusieurs clubs de lecture de la métropole lyonnaise.', NULL FROM `user` WHERE id = 1122 AND role = 'auteur';
INSERT INTO fiche_auteur_ouvrage (id_user, titre, editeur, annee, ordre) SELECT 1122, 'Coup franc', 'Autoédition', 2024, 0 FROM DUAL WHERE EXISTS (SELECT 1 FROM fiche_auteur WHERE id_user = 1122) AND NOT EXISTS (SELECT 1 FROM fiche_auteur_ouvrage WHERE id_user = 1122 AND titre = 'Coup franc');
INSERT IGNORE INTO fiche_auteur (id_user, nom_plume, slug, biographie, lien_site) SELECT id, 'Hélène Vidal', 'helene-vidal', 'Hélène Vidal partage sa vie entre Montpellier et les Cévennes, où elle cultive un grand potager. Elle écrit des guides pratiques simples sur le jardinage au naturel et la cuisine de saison, illustrés de ses propres photographies.', NULL FROM `user` WHERE id = 1123 AND role = 'auteur';
INSERT INTO fiche_auteur_ouvrage (id_user, titre, editeur, annee, ordre) SELECT 1123, 'Mon potager sans arrosage', 'Autoédition', 2022, 0 FROM DUAL WHERE EXISTS (SELECT 1 FROM fiche_auteur WHERE id_user = 1123) AND NOT EXISTS (SELECT 1 FROM fiche_auteur_ouvrage WHERE id_user = 1123 AND titre = 'Mon potager sans arrosage');
