INSERT INTO fiche_auteur_ouvrage (id_user, titre, editeur, annee, ordre) SELECT 1123, 'Conserves de saison', 'Autoédition', 2025, 2 FROM DUAL WHERE EXISTS (SELECT 1 FROM fiche_auteur WHERE id_user = 1123) AND NOT EXISTS (SELECT 1 FROM fiche_auteur_ouvrage WHERE id_user = 1123 AND titre = 'Conserves de saison');
INSERT INTO candidature_auteur (id_user, nom_plume, biographie, motivation, ouvrages, lien_site, date_candidature) SELECT id, 'Maëlys Caron', 'Étudiante en lettres à Rennes, j''écris de la fantasy depuis le lycée. Mon premier roman suit une jeune cartographe chargée de dessiner un royaume dont les frontières changent chaque nuit.', 'J''aimerais présenter mon roman aux lecteurs de BibliOccaz et participer aux rencontres organisées par la librairie. J''ai déjà fait plusieurs lectures publiques dans la bibliothèque de mon quartier.', '[{"titre":"La Cartographe des brumes","editeur":"Autoédition","annee":2026,"isbn":null}]', NULL, '2026-10-12 18:42:00' FROM `user` WHERE id = 1103 AND role = 'client' AND NOT EXISTS (SELECT 1 FROM candidature_auteur WHERE id_user = 1103);
INSERT INTO candidature_auteur (id_user, nom_plume, biographie, motivation, ouvrages, lien_site, date_candidature) SELECT id, 'Romain Collet', 'Passionné d''histoire locale, je raconte en courts chapitres la vie des bords de Loire au XIXe siècle : mariniers, lavandières et petits métiers disparus.', 'Mon livre s''adresse aux curieux et aux familles. Je souhaite le faire connaître et proposer une rencontre-dédicace à la librairie.', '[{"titre":"Gens de Loire","editeur":"Éditions de la Gabare","annee":2025,"isbn":null}]', NULL, '2026-10-18 09:05:00' FROM `user` WHERE id = 1108 AND role = 'client' AND NOT EXISTS (SELECT 1 FROM candidature_auteur WHERE id_user = 1108);
INSERT INTO candidature_auteur (id_user, nom_plume, biographie, motivation, ouvrages, lien_site, date_candidature) SELECT id, 'Youssef El Amrani', 'Développeur à Marseille, j''écris des romans policiers qui se déroulent dans les quartiers nord et sur le port. Mon enquêtrice est une ancienne docker devenue détective.', 'Je voudrais une fiche auteur pour que les lecteurs retrouvent mes deux romans et soient prévenus de mes prochaines dédicaces.', '[{"titre":"Quai de la Joliette","editeur":"Autoédition","annee":2024,"isbn":null},{"titre":"Mistral noir","editeur":"Autoédition","annee":2026,"isbn":null}]', NULL, '2026-10-23 21:17:00' FROM `user` WHERE id = 1112 AND role = 'client' AND NOT EXISTS (SELECT 1 FROM candidature_auteur WHERE id_user = 1112);
INSERT INTO candidature_auteur (id_user, nom_plume, biographie, motivation, ouvrages, lien_site, date_candidature) SELECT id, 'Héloïse Gilbert', 'Orthophoniste à Poitiers, j''écris des albums pour aider les tout-petits à mettre des mots sur leurs émotions.', 'Mes albums sont utilisés par des collègues et des écoles maternelles. J''aimerais les proposer aux familles qui fréquentent BibliOccaz.', '[{"titre":"Petit Ours a peur du noir","editeur":"Autoédition","annee":2025,"isbn":null}]', NULL, '2026-10-27 14:30:00' FROM `user` WHERE id = 1119 AND role = 'client' AND NOT EXISTS (SELECT 1 FROM candidature_auteur WHERE id_user = 1119);
